import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CDS RADOS for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"CDS RADOS for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","RADOS","OSD","BlueStore","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/CDS_RADOS_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/CDS_RADOS_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/CDS_RADOS_for_Ceph_Developer_Summit_-_Vampire.md"};function l(n,t,p,s,d,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议是 2026 年 Ceph Developer Summit（CDS）的首个 RADOS 专项会议，由 Rad（演讲者）主持，Anthony 主持开场。会议介绍了代号 <strong>Vampire</strong> 版本的 RADOS 组件开发范围，涵盖多项关键特性与优化方向。演讲者特别声明：议题列表中的条目并非全部承诺落地，部分内容可能因情况变化被推迟。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-pool-migration-存储池迁移" tabindex="-1">1. Pool Migration（存储池迁移） <a class="header-anchor" href="#_1-pool-migration-存储池迁移" aria-label="Permalink to &quot;1. Pool Migration（存储池迁移）&quot;">​</a></h3><p>这是社区期待已久的功能。目前用户若需调整 Erasure Coding（EC）参数（如 K+M 值）或更换 EC 插件，必须完全手动迁移数据，包括手动管控 IO 流量以保证一致性，过程极为繁琐。</p><p>Umbrella 版本中已有来自 UK 团队（Jamie）的 tech preview PR，但仍存在若干 bug，且当时 scope 较紧，因此推迟至 Vampire。</p><p><strong>关键特点：</strong></p><ul><li>非破坏性迁移，后台执行，类似 backfill 机制</li><li>不局限于 EC 池之间，支持 EC 与 replicated pool 之间的相互迁移</li><li>未来有潜力支持跨集群迁移，但不在 Vampire 范围内</li></ul><p><strong>承诺程度：</strong> 强承诺（strongly committed）</p><h3 id="_2-stretch-cluster-改进" tabindex="-1">2. Stretch Cluster 改进 <a class="header-anchor" href="#_2-stretch-cluster-改进" aria-label="Permalink to &quot;2. Stretch Cluster 改进&quot;">​</a></h3><p>Ceph 此前已支持 stretch cluster，但仅限于 replicated 模式；引入 EC 支持将大幅改善 TCO（总拥有成本）。</p><p><strong>改进内容：</strong></p><ul><li>提供核心功能及 UX 改进</li><li>简化 CRUSH 规则创建流程</li><li>编排 tiebreaker monitor 选择</li><li>新增性能计数器（performance counters）用于调试</li></ul><p>主要负责人：Alex Donahue 及相关团队。</p><h3 id="_3-端到端-tracing-增强" tabindex="-1">3. 端到端 Tracing 增强 <a class="header-anchor" href="#_3-端到端-tracing-增强" aria-label="Permalink to &quot;3. 端到端 Tracing 增强&quot;">​</a></h3><p>现有端到端 client-to-object-store tracing 已实现较久（最初由 RGW 团队发起），但 trace points 主要集中在热 IO 路径。</p><p><strong>计划改进：</strong></p><ul><li>将 tracing 扩展至 OSD 其他部分，特别是 scrubbing 流程</li><li>将 tracing 框架从 Jaeger 迁移至 <strong>OpenTelemetry</strong></li></ul><h3 id="_4-opal-sed-自加密驱动-支持" tabindex="-1">4. Opal SED（自加密驱动）支持 <a class="header-anchor" href="#_4-opal-sed-自加密驱动-支持" aria-label="Permalink to &quot;4. Opal SED（自加密驱动）支持&quot;">​</a></h3><p>目前 Ceph 的 data-at-rest 加密由 OSD 自身执行，密钥存储在 monitor key-value store 中。这种方式对 CPU 和整体性能有较大影响。</p><p><strong>新功能目标：</strong></p><ul><li>集成带有内置加密处理器的硬件驱动（Opal SED — Self-Encrypting Drive）</li><li>OSD 负责配置驱动并注入密钥，将加密运算卸载至硬件</li></ul><h3 id="_5-ec-direct-reads-均衡读优化-来自-umbrella-的遗留工作" tabindex="-1">5. EC Direct Reads / 均衡读优化（来自 Umbrella 的遗留工作） <a class="header-anchor" href="#_5-ec-direct-reads-均衡读优化-来自-umbrella-的遗留工作" aria-label="Permalink to &quot;5. EC Direct Reads / 均衡读优化（来自 Umbrella 的遗留工作）&quot;">​</a></h3><p>Umbrella 版本引入了 EC direct reads，带来了均衡读（balance reads）和拆分读（split reads）的性能提升，同样适用于 replica pool。</p><p><strong>机制：</strong> 客户端将读操作拆分至多个 OSD，从不同副本分别获取数据，降低延迟并提升带宽。</p><p><strong>Vampire 目标：</strong> 修复 Umbrella 版本中发现的 bug，将其默认开启，完成功能稳定化。</p><h3 id="_6-ec-池-omap-sparse-read-支持扩展" tabindex="-1">6. EC 池 OMAP / Sparse Read 支持扩展 <a class="header-anchor" href="#_6-ec-池-omap-sparse-read-支持扩展" aria-label="Permalink to &quot;6. EC 池 OMAP / Sparse Read 支持扩展&quot;">​</a></h3><p>Umbrella 中已为 EC 池引入 OMAP 原生支持，客户端不再需要手动分离 index pool 和 data pool。</p><p><strong>Vampire 目标：</strong> 继续缩小 EC 与 replicated pool 之间的功能差距，新增 sparse read 和 map extend 支持。</p><p><strong>实际收益：</strong> 支持在 EC 池上托管 RBD 加密镜像。</p><h3 id="_7-ceph-mgr-可靠性改进" tabindex="-1">7. Ceph MGR 可靠性改进 <a class="header-anchor" href="#_7-ceph-mgr-可靠性改进" aria-label="Permalink to &quot;7. Ceph MGR 可靠性改进&quot;">​</a></h3><p>近期再次出现单个 Python 模块异常导致整个集群受影响的问题，MGR 的模块隔离性问题由来已久。</p><p><strong>探索方向：</strong></p><ul><li><strong>多进程支持</strong>：为每个 MGR 模块创建独立的 Python 解释器及 OS 进程（Patrick 正在推进）</li><li><strong>MGR map 粒度提升</strong>：允许多个 active MGR 实例同时运行，各自负责不同模块，互不重叠，提升可扩展性</li><li>将计算密集型模块（如 upmap 计算）从主 MGR 实例中剥离</li></ul><p><strong>承诺程度：</strong> 研究性探索，无明确承诺</p><h3 id="_8-慢-osd-检测机制" tabindex="-1">8. 慢 OSD 检测机制 <a class="header-anchor" href="#_8-慢-osd-检测机制" aria-label="Permalink to &quot;8. 慢 OSD 检测机制&quot;">​</a></h3><p>少量慢速 HDD 或 OSD 可能严重影响整个集群性能，且难以定位。现有 PR 已将检测逻辑放在 MGR 层，但也有人探讨在 BlueStore 及 OSD 上层实现。</p><p><strong>计划：</strong> 在 CDS 期间安排专题讨论，集体讨论最佳实现方案。</p><h3 id="_9-超大集群支持-65-pb" tabindex="-1">9. 超大集群支持（65+ PB） <a class="header-anchor" href="#_9-超大集群支持-65-pb" aria-label="Permalink to &quot;9. 超大集群支持（65+ PB）&quot;">​</a></h3><p>CRUSH 权重使用的数值类型限制了超大集群的扩展性。已有 PR 以向后兼容方式实现扩展，目标是在 Vampire 周期内合并并充分测试。</p><h3 id="_10-monitor-client-辅助连接-auxiliary-connections" tabindex="-1">10. Monitor Client 辅助连接（Auxiliary Connections） <a class="header-anchor" href="#_10-monitor-client-辅助连接-auxiliary-connections" aria-label="Permalink to &quot;10. Monitor Client 辅助连接（Auxiliary Connections）&quot;">​</a></h3><p>当前 mon client 仅维持一条连接至 monitor 子集群。若某 monitor 实例处于&quot;半死&quot;状态（被踢出 quorum 但 TCP 仍通），客户端无法感知，可能导致 1/3 的 OSD 长期连接至&quot;黑洞&quot;。</p><p><strong>提案：</strong> 增加可配置的辅助连接，让 mon client 同时与多个 monitor 实例通信，提升容错性（Nielsen 正在推进 POC）。</p><p><strong>当前状态：</strong> 需重新讨论整体设计理念，然后将 POC 转化为可合并的实现。</p><h3 id="_11-osd-map-存储带宽优化" tabindex="-1">11. OSD Map 存储带宽优化 <a class="header-anchor" href="#_11-osd-map-存储带宽优化" aria-label="Permalink to &quot;11. OSD Map 存储带宽优化&quot;">​</a></h3><p>网络层已对 OSD map 增量传输做了优化，但 OSD 收到增量后仍会将完整 map 写入 object store，造成存储带宽浪费。在大量 upmap 和频繁 rebalance 场景下尤为明显。</p><p><strong>计划：</strong> 参考现有提案，在 object store 层也实现增量存储优化。</p><h3 id="_12-ec-与-upmap-数据移动优化" tabindex="-1">12. EC 与 Upmap 数据移动优化 <a class="header-anchor" href="#_12-ec-与-upmap-数据移动优化" aria-label="Permalink to &quot;12. EC 与 Upmap 数据移动优化&quot;">​</a></h3><p>通过限制 acting set 变化范围来减少 EC 和 upmap 场景下不必要的数据移动，相关改动已有 PR 文档。</p><h3 id="_13-构建与调试工具改进" tabindex="-1">13. 构建与调试工具改进 <a class="header-anchor" href="#_13-构建与调试工具改进" aria-label="Permalink to &quot;13. 构建与调试工具改进&quot;">​</a></h3><ul><li><strong>mold linker 切换</strong>：Ronan 正在评估切换至 mold linker 以大幅缩短链接时间，需要进一步评估收益与成本</li><li><strong>帧指针（frame pointer）优化</strong>：目前 Ceph 在构建时省略帧指针以节省寄存器，但这使性能分析（profiling）变得非常困难，需要依赖不常见的 PMU 特性。建议在非生产构建类型中禁用此优化，降低开发者调试负担。</li></ul><h3 id="_14-bluestore-及-rados-近期-pr-合并" tabindex="-1">14. BlueStore 及 RADOS 近期 PR 合并 <a class="header-anchor" href="#_14-bluestore-及-rados-近期-pr-合并" aria-label="Permalink to &quot;14. BlueStore 及 RADOS 近期 PR 合并&quot;">​</a></h3><p>包含一批接近就绪的 PR，涉及：</p><ul><li>PG map 算法中的 monitor 部分</li><li>BlueStore 与 Ceph MON 共用的 KV 抽象层</li><li>RocksDB resharding 调整</li><li>列族（column families）错误配置检测</li></ul><p>这些 PR 已经过 Igor 等人审查，计划纳入 Vampire 范围。</p><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>状态</th></tr></thead><tbody><tr><td>Pool Migration</td><td>强承诺，已有 PR 待审查</td></tr><tr><td>Stretch Cluster EC 支持</td><td>积极推进</td></tr><tr><td>OpenTelemetry 迁移</td><td>计划中</td></tr><tr><td>Opal SED 支持</td><td>计划中</td></tr><tr><td>EC direct reads 稳定化</td><td>计划默认开启</td></tr><tr><td>EC OMAP 功能扩展</td><td>持续推进</td></tr><tr><td>MGR 可靠性</td><td>研究性，无硬承诺</td></tr><tr><td>慢 OSD 检测</td><td>安排 CDS 专题讨论</td></tr><tr><td>超大集群支持</td><td>计划合并 PR</td></tr><tr><td>Mon client 辅助连接</td><td>需重新讨论架构</td></tr><tr><td>OSD Map 存储优化</td><td>计划评估</td></tr></tbody></table><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ol><li><strong>Pool Migration PR</strong> 审查推进，修复剩余 bug，目标 Vampire 合并</li><li><strong>慢 OSD 检测</strong>：在 CDS 期间安排专项 brainstorm 会议</li><li><strong>Mon client 辅助连接</strong>：重新讨论设计哲学，推动 POC 实用化</li><li><strong>mold linker</strong> 评估：分析 POC 结果后做最终决策</li><li><strong>帧指针优化</strong>：全项目范围的讨论，涉及所有构建类型</li><li>下一次 CDS 会议安排在<strong>周四</strong>同一时间，关注 MGR 可靠性专项议题（Nithin 和 Yaroslav 主讲）</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Vampire 版本的 RADOS 范围涵盖了多个社区长期期待的特性，尤其是 pool migration 和 EC 功能完善方面有实质性进展。同时在集群可观测性（tracing）、可靠性（MGR 隔离、慢 OSD 检测）和性能优化（OSD map 存储、构建工具）方面也有多项探索。整体而言，这是一个功能丰富但部分内容仍需讨论和验证的版本规划。</p>',61)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
